  // core/views/split-flow-view.js
  var SplitFlowView = class extends View {
    constructor({ params, annotationsOverride = {}, kpis = ["wip", "completed", "first"], signalPersistent = false } = {}) {
      super();
      this.params = params;
      this.annotationsOverride = annotationsOverride;
      this.kpis = kpis;
      this.signalPersistent = signalPersistent;
      this.viewBox = { w: 960, h: 580 };
    }
    build() {
      const L = createLayers(this.svg, { width: this.viewBox.w });
      const s = this.strings;
      this.clock = createClockDisplay(L.control, { x: 24, y: 26 });
      this.panels = {};
      this.params.panels.forEach((p, i) => {
        const originY = 36 + i * 270;
        text(L.process, 24, originY + 14, s.t(p.label), "scm-panel-label");
        this.panels[p.key] = createFlowLinePanel(this, L.process, { params: p.params, originY, lineY: 140, kpiY: 50, kpis: this.kpis, annotationsOverride: this.annotationsOverride, panelKey: p.key, annotationY: 76, annotationYRight: 54, signalPersistent: this.signalPersistent });
      });
    }
    render(state, t, events) {
      const s = this.strings;
      for (const p of this.params.panels) {
        const ps = state.panels[p.key];
        const evs = events.filter((e) => e.panel === p.key);
        const first = ps.firstCompleteT;
        this.panels[p.key].render(ps, t, evs, { first: first !== null && first !== void 0 ? `${first.toFixed(1)} s` : s.t("kpi.none") });
      }
      this.clock.update({ t });
    }
  };

