  var P2PModel = class extends Model {
    setup() {
      const d = { ...D, ...this.params.durations || {} };
      this.d = d;
      this.mismatch = !!this.params.mismatch;
      this.objects = {
        doc: { id: "doc", kind: "card", code: "PR", zone: "hidden", anchor: null, motion: null, badge: null },
        goods: { id: "goods", kind: "material", code: null, zone: "hidden", anchor: null, motion: null, badge: null },
        invoice: { id: "invoice", kind: "card", code: "INV", zone: "hidden", anchor: null, motion: null, badge: null },
        payment: { id: "payment", kind: "financial", code: "\u20AC", zone: "hidden", anchor: null, motion: null, badge: null },
        clarify: { id: "clarify", kind: "card", code: "?", zone: "hidden", anchor: null, motion: null, badge: null }
      };
      this.stations = Object.fromEntries(P2P_STATIONS.map((id) => [id, { id, state: "idle", busy: null }]));
      this.kpi = { processing: 0, waiting: 0, rework: 0, grPosted: false, matched: false, paid: false };
      this._waitStart = {};
      this._buildTimeline();
    }
    // ---- timeline ---------------------------------------------------------------------------
    _buildTimeline() {
      const d = this.d;
      let t = 0;
      const S = (time, type, payload) => this.schedule(time, type, payload);
      S(t, "create", { obj: "doc", at: { kind: "station", id: "requisition" }, annotation: "annotation.prCreated" });
      S(t, "dwellStart", { obj: "doc", station: "requisition" });
      t += d.requisition;
      S(t, "dwellEnd", { obj: "doc", station: "requisition", dur: d.requisition });
      S(t, "move", { obj: "doc", to: { kind: "station", id: "approval" }, dur: d.docMove });
      t += d.docMove;
      S(t, "dwellStart", { obj: "doc", station: "approval" });
      t += d.approval;
      S(t, "dwellEnd", { obj: "doc", station: "approval", dur: d.approval, annotation: "annotation.approved" });
      S(t, "move", { obj: "doc", to: { kind: "station", id: "po" }, dur: d.docMove });
      t += d.docMove;
      S(t, "dwellStart", { obj: "doc", station: "po" });
      t += d.po;
      S(t, "dwellEnd", { obj: "doc", station: "po", dur: d.po });
      S(t, "transform", { obj: "doc", code: "PO", annotation: "annotation.poReleased" });
      S(t, "move", { obj: "doc", to: { kind: "supplier", id: "poIn" }, lane: "po", dur: d.poTransit });
      t += d.poTransit;
      S(t, "arrive", { obj: "doc", at: { kind: "supplier", id: "poIn" } });
      const tPoAtSupplier = t;
      const tShip = tPoAtSupplier + d.supplierLead;
      S(tShip, "create", { obj: "goods", at: { kind: "supplier", id: "goodsOut" }, annotation: "annotation.goodsShipped" });
      S(tShip, "move", { obj: "goods", to: { kind: "station", id: "goodsReceipt" }, lane: "goods", dur: d.goodsTransit });
      const tGrArrive = tShip + d.goodsTransit;
      S(tGrArrive, "dwellStart", { obj: "goods", station: "goodsReceipt" });
      const tGrPosted = tGrArrive + d.grPosting;
      S(tGrPosted, "dwellEnd", { obj: "goods", station: "goodsReceipt", dur: d.grPosting, annotation: "annotation.grPosted" });
      S(tGrPosted, "flag", { key: "grPosted" });
      S(tGrPosted, "move", { obj: "goods", to: { kind: "stock", id: "stock" }, dur: d.docMove });
      const tInvSend = tShip + d.invoiceDelay;
      S(tInvSend, "create", { obj: "invoice", at: { kind: "supplier", id: "invoiceOut" } });
      S(tInvSend, "move", { obj: "invoice", to: { kind: "station", id: "invoiceMatch" }, lane: "invoice", dur: d.invoiceTransit });
      const tInvArrive = tInvSend + d.invoiceTransit;
      let tMatchStart = tInvArrive;
      if (tGrPosted > tInvArrive) {
        S(tInvArrive, "wait", { obj: "invoice", station: "invoiceMatch", reason: "waitingForGr", annotation: "annotation.invoiceWaitsForGr" });
        S(tGrPosted, "waitEnd", { obj: "invoice" });
        tMatchStart = tGrPosted;
      }
      S(tMatchStart, "dwellStart", { obj: "invoice", station: "invoiceMatch" });
      let tMatched = tMatchStart + d.match;
      if (this.mismatch) {
        S(tMatched, "dwellEnd", { obj: "invoice", station: "invoiceMatch", dur: d.match });
        S(tMatched, "mismatch", { obj: "invoice", annotation: "annotation.mismatch" });
        S(tMatched, "wait", { obj: "invoice", station: "invoiceMatch", reason: "clarifying" });
        S(tMatched, "create", { obj: "clarify", at: { kind: "station", id: "invoiceMatch" } });
        S(tMatched, "move", { obj: "clarify", to: { kind: "station", id: "goodsReceipt" }, lane: "rework", dur: d.clarifyTransit, annotation: "annotation.clarifyToGr" });
        const tClarAtGr = tMatched + d.clarifyTransit;
        S(tClarAtGr, "dwellStart", { obj: "clarify", station: "goodsReceipt" });
        const tCorrected = tClarAtGr + d.grCorrection;
        S(tCorrected, "dwellEnd", { obj: "clarify", station: "goodsReceipt", dur: d.grCorrection, annotation: "annotation.grCorrected" });
        S(tCorrected, "flag", { key: "rework" });
        S(tCorrected, "move", { obj: "clarify", to: { kind: "station", id: "invoiceMatch" }, lane: "reworkBack", dur: d.returnTransit });
        const tBack = tCorrected + d.returnTransit;
        S(tBack, "remove", { obj: "clarify" });
        S(tBack, "waitEnd", { obj: "invoice" });
        S(tBack, "clearBadge", { obj: "invoice" });
        S(tBack, "dwellStart", { obj: "invoice", station: "invoiceMatch" });
        tMatched = tBack + d.rematch;
      }
      S(tMatched, "dwellEnd", { obj: "invoice", station: "invoiceMatch", dur: this.mismatch ? d.rematch : d.match, annotation: "annotation.threeWayMatch" });
      S(tMatched, "flag", { key: "matched" });
      S(tMatched, "move", { obj: "invoice", to: { kind: "station", id: "payment" }, dur: d.docMove });
      const tPayStart = tMatched + d.docMove;
      S(tPayStart, "dwellStart", { obj: "invoice", station: "payment" });
      const tPayReleased = tPayStart + d.paymentPrep;
      S(tPayReleased, "dwellEnd", { obj: "invoice", station: "payment", dur: d.paymentPrep });
      S(tPayReleased, "move", { obj: "invoice", to: { kind: "archive", id: "archive" }, dur: d.docMove });
      S(tPayReleased, "create", { obj: "payment", at: { kind: "station", id: "payment" } });
      S(tPayReleased, "move", { obj: "payment", to: { kind: "supplier", id: "paymentIn" }, lane: "payment", dur: d.paymentTransit });
      const tPaid = tPayReleased + d.paymentTransit;
      S(tPaid, "arrive", { obj: "payment", at: { kind: "supplier", id: "paymentIn" } });
      S(tPaid, "flag", { key: "paid", annotation: "annotation.paid", done: true });
    }
    // ---- handlers -----------------------------------------------------------------------------
    handle(ev) {
      const o = ev.obj ? this.objects[ev.obj] : null;
      const st = ev.station ? this.stations[ev.station] : null;
      switch (ev.type) {
        case "create":
          o.zone = "placed";
          o.anchor = ev.at;
          o.motion = null;
          break;
        case "dwellStart":
          o.zone = "station";
          o.anchor = { kind: "station", id: ev.station };
          o.motion = null;
          st.state = "running";
          st.busy = o.id;
          break;
        case "dwellEnd":
          this.kpi.processing += ev.dur;
          st.state = "idle";
          st.busy = null;
          break;
        case "move":
          o.motion = { from: o.anchor, to: ev.to, lane: ev.lane || null, t0: ev.t, t1: ev.t + ev.dur };
          o.zone = "moving";
          o.anchor = ev.to;
          break;
        case "arrive":
          o.zone = "placed";
          o.anchor = ev.at;
          o.motion = null;
          break;
        case "transform":
          o.code = ev.code;
          break;
        case "wait":
          o.zone = "waiting";
          o.anchor = { kind: "station", id: ev.station };
          o.motion = null;
          o.waitReason = ev.reason;
          this._waitStart[o.id] = ev.t;
          st.state = "starved";
          break;
        case "waitEnd":
          if (this._waitStart[o.id] !== void 0) {
            this.kpi.waiting += ev.t - this._waitStart[o.id];
            delete this._waitStart[o.id];
          }
          o.zone = "placed";
          o.waitReason = null;
          break;
        case "mismatch":
          o.badge = "!";
          break;
        case "clearBadge":
          o.badge = null;
          break;
        case "remove":
          o.zone = "hidden";
          o.motion = null;
          break;
        case "flag":
          if (ev.key === "rework") this.kpi.rework += 1;
          else this.kpi[ev.key] = true;
          if (ev.done) this.markDone();
          break;
        default:
          break;
      }
      return { token: ev.obj || null, station: ev.station || null, annotation: ev.annotation || null, to: ev.to ? `${ev.to.kind}:${ev.to.id}` : null };
    }
    snapshot() {
      return { t: +this.t.toFixed(3), processing: +this.kpi.processing.toFixed(2), waiting: +this.kpi.waiting.toFixed(2), rework: this.kpi.rework, matched: this.kpi.matched, paid: this.kpi.paid };
    }
    getState() {
      const waitingNow = Object.entries(this._waitStart).reduce((acc, [, t0]) => acc + (this.t - t0), 0);
      return {
        t: this.t,
        objects: Object.values(this.objects).map((o) => ({ ...o, anchor: o.anchor ? { ...o.anchor } : null, motion: o.motion ? { ...o.motion } : null })),
        stations: Object.values(this.stations).map((s) => ({ ...s })),
        kpi: { ...this.kpi, waiting: this.kpi.waiting + waitingNow },
        done: this.isDone()
      };
    }
  };

