      "annotation.firstOrder.wwA": "\u30EF\u30B0\u30CA\u30FC\u30FB\u30DB\u30A4\u30C3\u30C8\u30F3\u6CD5\u306F\u6700\u521D\u306E\u767A\u6CE8\u306E\u524D\u306B\u5168\u671F\u9593\u3092\u89E3\u3044\u3066\u3044\u308B\u3002\u305D\u308C\u306F\u524D\u63D0\u3067\u3042\u3063\u3066\u3001\u7D50\u679C\u3067\u306F\u306A\u3044\u3002",
      "annotation.firstOrder.smB": "\u540C\u3058\u5341\u4E8C\u306E\u6570\u3001\u4E26\u3073\u3060\u3051\u304C\u9055\u3046\u3002\u30B7\u30EB\u30D0\u30FC\u30FB\u30DF\u30FC\u30EB\u6CD5\u306F\u4E8C\u671F\u5206\u3057\u304B\u624B\u5F53\u3066\u3057\u306A\u3044 \u2014\u2014 \u7B2C\u4E09\u671F\u306B\u306F\u56DB\u500B\u304C\u8981\u308B\u306E\u306B\u3002",
      "annotation.firstOrder.wwB": "\u540C\u3058\u5341\u4E8C\u306E\u6570\u3001\u4E26\u3073\u3060\u3051\u304C\u9055\u3046\u3002\u6700\u9069\u89E3\u306F\u56DB\u671F\u5206\u3092\u307E\u3068\u3081\u3066\u624B\u5F53\u3066\u3057\u3001\u305D\u306E\u5206\u306E\u5728\u5EAB\u3092\u62B1\u3048\u308B\u3002",
      "annotation.lotArrived": "\u767A\u6CE8\u3057\u305F\u5206\u304C\u3059\u3079\u3066\u5009\u5EAB\u306B\u4E26\u3093\u3060\u3002\u3053\u306E\u671F\u304C\u4F7F\u3046\u306E\u306F\u305D\u306E\u4E00\u90E8\u3067\u3001\u6B8B\u308A\u306F\u6301\u3061\u8D8A\u3055\u308C\u308B\u3002",
      "annotation.lotArrived.lfl": "\u767A\u6CE8\u3057\u305F\u5206\u304C\u5009\u5EAB\u306B\u4E26\u3073\u3001\u3053\u306E\u671F\u304C\u305D\u308C\u3092\u4F7F\u3044\u5207\u308B\u3002\u6301\u3061\u8D8A\u3057\u306F\u751F\u3058\u306A\u3044\u3002",
      "annotation.firstCarry": "\u671F\u304C\u7D42\u308F\u308A\u3001\u5009\u5EAB\u306B\u306F\u307E\u3060\u5728\u5EAB\u304C\u3042\u308B\u3002\u4E0B\u306E\u8A08\u6570\u5668\u306F\u3001\u305D\u3053\u306B\u7ACB\u3063\u3066\u3044\u308B\u500B\u6570\u3068\u540C\u3058\u3060\u3051\u30DE\u30B9\u76EE\u3092\u9032\u3081\u308B\u3002",
      "annotation.noCarry": "\u671F\u304C\u7D42\u308F\u308A\u3001\u5009\u5EAB\u306F\u7A7A\u3067\u3042\u308B\u3002\u4E0B\u306E\u8A08\u6570\u5668\u306F\u52D5\u304B\u306A\u3044 \u2014\u2014 \u3053\u306E\u904B\u8EE2\u3067\u306F\u6700\u5F8C\u307E\u3067\u52D5\u304B\u306A\u3044\u3002",
      "annotation.peakDemand": "\u7CFB\u5217\u3067\u6700\u5927\u306E\u671F\u3001\u4E94\u500B\u304C\u4E00\u5EA6\u306B\u51FA\u3066\u3044\u304F\u3002\u305D\u308C\u306F\u3069\u3053\u304B\u3089\u6765\u305F\u306E\u304B \u2014\u2014 \u4ECA\u65E5\u306E\u767A\u6CE8\u304B\u3001\u6301\u3061\u8D8A\u3057\u305F\u5728\u5EAB\u304B\u3002",
      "annotation.close": "\u5341\u4E8C\u671F\u3001\u4E8C\u5341\u56DB\u500B\u3001\u3069\u306E\u671F\u306E\u9700\u8981\u3082\u6E80\u305F\u3055\u308C\u305F\u3002",
      "annotation.close.lflA": "\u767A\u6CE8\u5341\u4E8C\u56DE\u3001\u6301\u3061\u8D8A\u3057\u30BC\u30ED\u3001168 \u8CA8\u5E63\u5358\u4F4D\u3002\u9700\u8981\u306E\u4E26\u3073\u306F\u4F55\u3082\u5909\u3048\u306A\u304B\u3063\u305F\u3002",
      "annotation.close.lflB": "\u307E\u305F\u767A\u6CE8\u5341\u4E8C\u56DE\u3001\u307E\u305F\u6301\u3061\u8D8A\u3057\u30BC\u30ED\u3001168 \u8CA8\u5E63\u5358\u4F4D\u3002\u30ED\u30C3\u30C8\u30FB\u30D5\u30A9\u30FC\u30FB\u30ED\u30C3\u30C8\u306B\u306F\u4E8C\u3064\u306E\u7CFB\u5217\u306E\u9055\u3044\u304C\u5206\u304B\u3089\u306A\u3044\u3002",
      "annotation.close.smA": "\u767A\u6CE8\u56DB\u56DE\u3001\u6301\u3061\u8D8A\u3057\u5341\u516B\u300174 \u8CA8\u5E63\u5358\u4F4D\u3002\u516D\u500B\u305A\u3064\u56DB\u30ED\u30C3\u30C8 \u2014\u2014 \u3053\u306E\u7CFB\u5217\u3067\u306F\u30D2\u30E5\u30FC\u30EA\u30B9\u30C6\u30A3\u30C3\u30AF\u304C\u304D\u308F\u3081\u3066\u6574\u3063\u305F\u7B54\u3048\u3092\u51FA\u3057\u305F\u3002",
      "annotation.close.wwA": "\u767A\u6CE8\u56DB\u56DE\u3001\u6301\u3061\u8D8A\u3057\u5341\u516B\u300174 \u8CA8\u5E63\u5358\u4F4D\u3002\u3053\u308C\u306F\u3053\u306E\u7CFB\u5217\u306E\u3042\u3089\u3086\u308B\u767A\u6CE8\u30D1\u30BF\u30FC\u30F3\u306E\u306A\u304B\u306E\u6700\u5C0F\u3067\u3042\u308B\u3002",
      "annotation.close.smB": "\u767A\u6CE8\u4E94\u56DE\u3001\u6301\u3061\u8D8A\u3057\u5341\u516B\u300188 \u8CA8\u5E63\u5358\u4F4D\u3002\u5148\u307B\u3069\u3068\u540C\u3058\u4E8C\u5341\u56DB\u500B\u304C\u3001\u4E26\u3073\u3092\u5909\u3048\u305F\u3060\u3051\u3067\u3042\u308B\u3002",
      "annotation.close.wwB": "\u767A\u6CE8\u4E09\u56DE\u3001\u6301\u3061\u8D8A\u3057\u4E09\u5341\u300172 \u8CA8\u5E63\u5358\u4F4D\u3002\u5728\u5EAB\u306F\u591A\u304F\u767A\u6CE8\u306F\u5C11\u306A\u3044 \u2014\u2014 \u305D\u3057\u3066\u3053\u306E\u7CFB\u5217\u306E\u3042\u3089\u3086\u308B\u767A\u6CE8\u30D1\u30BF\u30FC\u30F3\u306E\u306A\u304B\u306E\u6700\u5C0F\u3067\u3042\u308B\u3002",
